      nereden: { site: 'Analiz haritaları → 300 hPa · alternatif: Tropical Tidbits 250/300 hPa jet', url: 'https://www.tropicaltidbits.com', adim: ['İzotak renk ölçeğini (kt) slayta küçük not olarak ekle.', 'İstanbul rüzgârını sondajın 300 hPa satırından doğrula.'] },
